/*
 * display.c — font rendering and framebuffer drawing
 *
 * Uses anti-aliased proportional fonts generated by gen_fonts.py
 * from DejaVu Sans (small, medium, large sizes).
 */

#include "display.h"
#include "fonts.h"
#include <string.h>

static shelbourne_t *hw;

void display_init(shelbourne_t *h)
{
    hw = h;
}

/* ── Generic proportional font renderer ──────────────────────── */

static int glyph_width(const font_t *f, char c)
{
    if (c < 32 || c > 126) c = '?';
    return f->widths[c - 32];
}

static int string_width(const font_t *f, const char *s)
{
    int w = 0;
    for (int i = 0; s[i]; i++)
        w += glyph_width(f, s[i]);
    return w;
}

static void draw_char(const font_t *f, int x, int y, char c)
{
    uint8_t *fb = shelbourne_display_buffer(hw);
    if (!fb) return;
    if (c < 32 || c > 126) c = '?';

    int idx = c - 32;
    int w = f->widths[idx];
    int h = f->height;
    const uint8_t *data = f->data + f->offsets[idx];

    for (int row = 0; row < h; row++) {
        int py = y + row;
        if (py < 0 || py >= SHELBOURNE_FB_HEIGHT) {
            data += w;
            continue;
        }
        for (int col = 0; col < w; col++) {
            int px = x + col;
            uint8_t val = *data++;
            if (px >= 0 && px < SHELBOURNE_FB_WIDTH && val > 0) {
                /* Alpha-blend: blend glyph pixel over existing background */
                uint8_t bg = fb[py * SHELBOURNE_FB_WIDTH + px];
                uint8_t out = bg + ((val * (255 - bg)) >> 8);
                fb[py * SHELBOURNE_FB_WIDTH + px] = out;
            }
        }
    }
}

static void draw_string(const font_t *f, int x, int y, const char *s)
{
    for (int i = 0; s[i]; i++) {
        draw_char(f, x, y, s[i]);
        x += glyph_width(f, s[i]);
    }
}

static void draw_centered(const font_t *f, int y, const char *s)
{
    int w = string_width(f, s);
    int x = (SHELBOURNE_FB_WIDTH - w) / 2;
    draw_string(f, x, y, s);
}

/* ── Public API ──────────────────────────────────────────────── */

void fb_putstr(int x, int y, const char *s)
{
    draw_string(&font_small, x, y, s);
}

int fb_text_width(const char *s)
{
    return string_width(&font_small, s);
}

void fb_center_2x(int y, const char *s)
{
    draw_centered(&font_medium, y, s);
}

void fb_center_4x(int y, const char *s)
{
    draw_centered(&font_large, y, s);
}

int fb_wrap_2x(int y, int y_max, const char *text)
{
    int line_h = font_medium.height + 2;

    while (*text && y + font_medium.height <= y_max) {
        /* Find how many chars fit on one line */
        int len = strlen(text);
        int line_chars = 0;
        int line_w = 0;

        for (int i = 0; i < len; i++) {
            int cw = glyph_width(&font_medium, text[i]);
            if (line_w + cw > SHELBOURNE_FB_WIDTH)
                break;
            line_w += cw;
            line_chars = i + 1;
        }

        if (line_chars == 0) line_chars = 1;  /* at least one char */

        /* Word-break: if not at end, back up to last space */
        if (line_chars < len) {
            int brk = line_chars;
            while (brk > 0 && text[brk] != ' ') brk--;
            if (brk > 0) line_chars = brk;
        }

        /* Render this line centered */
        char line[128];
        if (line_chars >= (int)sizeof(line))
            line_chars = sizeof(line) - 1;
        memcpy(line, text, line_chars);
        line[line_chars] = '\0';
        draw_centered(&font_medium, y, line);

        text += line_chars;
        while (*text == ' ') text++;
        y += line_h;
    }
    return y;
}

void display_logo(const uint8_t *logo)
{
    uint8_t *fb = shelbourne_display_buffer(hw);
    if (fb && logo)
        memcpy(fb, logo, SHELBOURNE_FB_SIZE);
}
